import os, re
from pathlib import Path
from PIL import Image, ImageOps
import pytesseract
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP
from openpyxl import Workbook

img_dir = Path('/app/workspace/dataset/img')
files = sorted([p for p in img_dir.iterdir() if p.is_file()])

# Patterns
EXCLUDE = [
    'SUBTOTAL','SUB TOTAL','TAX','GST','SST','DISCOUNT','CHANGE','CASH TENDERED'
]
KEYWORDS_PRIORITY = [
    ['GRAND TOTAL'],
    ['TOTAL RM','TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL','AMOUNT','TOTAL DUE','AMOUNT DUE','BALANCE DUE','NETT TOTAL','NET TOTAL']
]

month_map = {
    'JAN':1,'FEB':2,'MAR':3,'APR':4,'MAY':5,'JUN':6,'JUL':7,'AUG':8,'SEP':9,'SEPT':9,'OCT':10,'NOV':11,'DEC':12
}

# Regex for amounts
decimal_re = re.compile(r'(\d{1,3}(?:,\d{3})*|\d+)\.(\d{2})')
int_re = re.compile(r'(?<!\d)(\d{1,3}(?:,\d{3})*|\d+)(?!\d)')


def normalize_text(text: str) -> str:
    # Fix common OCR confusions between digits and letters when adjacent to digits
    text = re.sub(r'(?<=\d)[Oo](?=\d)', '0', text)
    text = re.sub(r'(?<=\d)[Il](?=\d)', '1', text)
    return text


def parse_date_candidate(y, m, d):
    try:
        return datetime(int(y), int(m), int(d)).date().isoformat()
    except Exception:
        return None


def extract_date(text: str):
    text = normalize_text(text)

    # Year-first patterns
    for m in re.finditer(r'(\d{4})[\-/\.](\d{1,2})[\-/\.](\d{1,2})', text):
        y, mo, d = m.groups()
        iso = parse_date_candidate(y, mo, d)
        if iso:
            return iso

    # Day-first patterns
    for m in re.finditer(r'(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{2,4})', text):
        d, mo, y = m.groups()
        if len(y) == 2:
            y = str(2000 + int(y))
        iso = parse_date_candidate(y, mo, d)
        if iso:
            return iso

    # Month name patterns
    # e.g. 12 JAN 2023, 12-JAN-23, JAN 12 2023
    for m in re.finditer(r'(\d{1,2})\s*[\-/\.]?\s*([A-Za-z]{3,5})\s*[\-/\.]?\s*(\d{2,4})', text, re.IGNORECASE):
        d, mon, y = m.groups()
        mon = mon.upper()
        mon = mon[:4] if mon.startswith('SEPT') else mon[:3]
        if mon in month_map:
            if len(y) == 2:
                y = str(2000 + int(y))
            iso = parse_date_candidate(y, month_map[mon], d)
            if iso:
                return iso

    for m in re.finditer(r'([A-Za-z]{3,5})\s*(\d{1,2})\s*,?\s*(\d{2,4})', text, re.IGNORECASE):
        mon, d, y = m.groups()
        mon = mon.upper()
        mon = mon[:4] if mon.startswith('SEPT') else mon[:3]
        if mon in month_map:
            if len(y) == 2:
                y = str(2000 + int(y))
            iso = parse_date_candidate(y, month_map[mon], d)
            if iso:
                return iso

    return None


def extract_amount_from_line(line: str):
    # Prefer decimal numbers
    decs = decimal_re.findall(line)
    if decs:
        # get last match full number
        # reconstruct to include commas
        matches = list(decimal_re.finditer(line))
        last = matches[-1].group(0)
        return last
    # fallback to integer if no decimals
    ints = list(int_re.finditer(line))
    if ints:
        last = ints[-1].group(0)
        return last
    return None


def format_amount(raw: str):
    if raw is None:
        return None
    s = raw.replace(',', '')
    try:
        dec = Decimal(s)
        return str(dec.quantize(Decimal('0.00'), rounding=ROUND_HALF_UP))
    except Exception:
        return None


def line_has_exclusion(line_upper: str):
    return any(k in line_upper for k in EXCLUDE)


def extract_total_amount(text: str):
    text = normalize_text(text)
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    upper_lines = [ln.upper() for ln in lines]

    for group in KEYWORDS_PRIORITY:
        for i, uline in enumerate(upper_lines):
            if line_has_exclusion(uline):
                continue
            if any(k in uline for k in group):
                amt = extract_amount_from_line(lines[i])
                if amt:
                    return format_amount(amt)
                # fallback to next line
                if i + 1 < len(lines):
                    next_u = upper_lines[i+1]
                    if not line_has_exclusion(next_u):
                        amt = extract_amount_from_line(lines[i+1])
                        if amt:
                            return format_amount(amt)
    return None


def ocr_image(path: Path):
    img = Image.open(path)
    img = img.convert('L')
    img = ImageOps.autocontrast(img)
    # upscale for better OCR
    scale = 2
    img = img.resize((img.width * scale, img.height * scale))
    # simple threshold
    img = img.point(lambda x: 0 if x < 150 else 255, '1')
    config = '--oem 3 --psm 6'
    return pytesseract.image_to_string(img, config=config)

rows = []

for path in files:
    if path.suffix.lower() not in ['.jpg', '.jpeg', '.png', '.tif', '.tiff', '.bmp']:
        continue
    text = ocr_image(path)
    date = extract_date(text)
    total = extract_total_amount(text)
    rows.append((path.name, date, total))

# sort by filename
rows.sort(key=lambda x: x[0])

wb = Workbook()
# remove default sheet
if wb.active:
    wb.remove(wb.active)
ws = wb.create_sheet('results')
ws.append(['filename','date','total_amount'])
for r in rows:
    ws.append(list(r))

out_path = Path('/app/workspace/stat_ocr.xlsx')
wb.save(out_path)
print('Wrote', out_path)
PY"}

